/// Replaces the committed Tile Map as one semantic undo entry.
///
/// Active pointer gestures are never crossed, and invalid persisted documents are rejected
/// before committed state changes.
///
/// # Errors
///
/// Returns [`Native2dAuthoringError::GestureAlreadyActive`] while a gesture is active, or
/// [`Native2dAuthoringError::InvalidDocument`] when the replacement violates Tile Map
/// invariants.
pub fn replace_document(
    &mut self,
    replacement: TileMapDocument,
) -> Result<bool, Native2dAuthoringError> {
    if self.active.is_some() {
        return Err(Native2dAuthoringError::GestureAlreadyActive);
    }
    let errors = replacement.validate();
    if !errors.is_empty() {
        return Err(Native2dAuthoringError::InvalidDocument(errors.join("; ")));
    }
    if self.document == replacement {
        return Ok(false);
    }
    self.undo.push(self.document.clone());
    self.document = replacement;
    Ok(true)
}

